<?php
use App\Application\Identity\InvitationService;use App\Models\Tenant;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;
uses(RefreshDatabase::class);
test('an invitation token is stored only as a hash and can be accepted once',function(){$admin=User::factory()->create();$user=User::factory()->create();$tenant=Tenant::create(['type'=>'BROKER','legal_name'=>'Safe Broker','slug'=>'safe-broker','status'=>'ACTIVE','country_code'=>'CM','currency'=>'XAF','primary_locale'=>'en','settings'=>[]]);$result=app(InvitationService::class)->issue($tenant,$admin,$user->email,null,'BROKER_STAFF');expect($result['invitation']->getRawOriginal('token_hash'))->toBe(hash('sha256',$result['token']))->and($result['invitation']->getRawOriginal('token_hash'))->not->toBe($result['token']);$membership=app(InvitationService::class)->accept($result['token'],$user);expect($membership->status)->toBe('ACTIVE')->and($result['invitation']->refresh()->status)->toBe('ACCEPTED');});
